    74	    const styles = useThemeStyles();
    75	    const {translate} = useLocalize();
    76	
    77	    const zipSampleFormat = (country && (CONST.COUNTRY_ZIP_REGEX_DATA[country] as CountryZipRegex)?.samples) ?? '';
    78	
    79	    const zipFormat = translate('common.zipCodeExampleFormat', {zipSampleFormat});
    80	
    81	    const isUSAForm = country === CONST.COUNTRY.US;
    82	
    83	    /**
    84	     * @param translate - translate function
