    88	     */
    89	
    90	    const validator = useCallback(
    91	        (values: FormOnyxValues<typeof ONYXKEYS.FORMS.GET_PHYSICAL_CARD_FORM | typeof ONYXKEYS.FORMS.HOME_ADDRESS_FORM>): Errors => {
    92	            const errors: Errors & {
    93	                zipPostCode?: string | string[];
    94	            } = {};
    95	            const requiredFields = ['addressLine1', 'city', 'country', 'state'] as const;
    96	
    97	            // Check "State" dropdown is a valid state if selected Country is USA
    98	            if (values.country === CONST.COUNTRY.US && !values.state) {
    99	                errors.state = translate('common.error.fieldRequired');
   100	            }
   101	
   102	            // Add "Field required" errors if any required field is empty
   103	            requiredFields.forEach((fieldKey) => {
   104	                const fieldValue = values[fieldKey] ?? '';
   105	                if (ValidationUtils.isRequiredFulfilled(fieldValue)) {
   106	                    return;
   107	                }
   108	
   109	                errors[fieldKey] = translate('common.error.fieldRequired');
   110	            });
   111	
   112	            // If no country is selected, default value is an empty string and there's no related regex data so we default to an empty object
   113	            const countryRegexDetails = (values.country ? CONST.COUNTRY_ZIP_REGEX_DATA?.[values.country] : {}) as CountryZipRegex;
   114	
   115	            // The postal code system might not exist for a country, so no regex either for them.
   116	            const countrySpecificZipRegex = countryRegexDetails?.regex;
   117	            const countryZipFormat = countryRegexDetails?.samples ?? '';
   118	
   119	            ErrorUtils.addErrorMessage(errors, 'firstName', translate('bankAccount.error.firstName'));
   120	
   121	            if (countrySpecificZipRegex) {
   122	                if (!countrySpecificZipRegex.test(values.zipPostCode?.trim().toUpperCase())) {
   123	                    if (ValidationUtils.isRequiredFulfilled(values.zipPostCode?.trim())) {
   124	                        errors.zipPostCode = translate('privatePersonalDetails.error.incorrectZipFormat', {zipFormat: countryZipFormat});
   125	                    } else {
   126	                        errors.zipPostCode = translate('common.error.fieldRequired');
   127	                    }
   128	                }
   129	            } else if (!CONST.GENERIC_ZIP_CODE_REGEX.test(values?.zipPostCode?.trim()?.toUpperCase() ?? '')) {
   130	                errors.zipPostCode = translate('privatePersonalDetails.error.incorrectZipFormat');
   131	            }
